WITH RECURSIVE f AS (SELECT * FROM facility_terms), p AS (SELECT * FROM period_cases), c AS (SELECT * FROM collateral_cases), b AS (SELECT c.scenario, p.period, (c.credit_card_receivables+c.pharmacy_receivables)*f.receivable_rate AS a, c.script_liquidation_value*f.script_rate AS s, c.regular_inventory_cost*c.regular_appraisal*CASE WHEN p.seasonal=1 THEN f.seasonal_inventory_rate ELSE f.ordinary_inventory_rate END AS ra, c.perishable_inventory_cost*c.perishable_appraisal*CASE WHEN p.seasonal=1 THEN f.seasonal_inventory_rate ELSE f.ordinary_inventory_rate END AS pa, c.regular_purchase_fraction*c.regular_appraisal*CASE WHEN p.seasonal=1 THEN f.seasonal_inventory_rate ELSE f.ordinary_inventory_rate END AS rp, (1.0-c.regular_purchase_fraction)*c.perishable_appraisal*CASE WHEN p.seasonal=1 THEN f.seasonal_inventory_rate ELSE f.ordinary_inventory_rate END AS pp, c.availability_reserves AS res, f.commitment, f.shared_dollar_cap, c.loans+c.letters_of_credit AS e FROM c CROSS JOIN p CROSS JOIN f), bs(scenario,period,a,s,ra,pa,rp,pp,res,commitment,shared_dollar_cap,e,lo,hi,n) AS (SELECT scenario,period,a,s,ra,pa,rp,pp,res,commitment,shared_dollar_cap,e,0.0,commitment+1.0,0 FROM b UNION ALL SELECT scenario,period,a,s,ra,pa,rp,pp,res,commitment,shared_dollar_cap,e,CASE WHEN (lo+hi)/2.0<=MIN(commitment,a+ra+rp*(lo+hi)/2.0-res+MIN(s,MIN(shared_dollar_cap,CASE WHEN (a+ra+rp*(lo+hi)/2.0+pa+pp*(lo+hi)/2.0-res)<3.0*s THEN (a+ra+rp*(lo+hi)/2.0+pa+pp*(lo+hi)/2.0-res)/3.0 ELSE (a+ra+rp*(lo+hi)/2.0+pa+pp*(lo+hi)/2.0-res+s)/4.0 END))+MIN(pa+pp*(lo+hi)/2.0,(a+ra+rp*(lo+hi)/2.0+s-res)/3.0))-e+1e-12 THEN (lo+hi)/2.0 ELSE lo END,CASE WHEN (lo+hi)/2.0<=MIN(commitment,a+ra+rp*(lo+hi)/2.0-res+MIN(s,MIN(shared_dollar_cap,CASE WHEN (a+ra+rp*(lo+hi)/2.0+pa+pp*(lo+hi)/2.0-res)<3.0*s THEN (a+ra+rp*(lo+hi)/2.0+pa+pp*(lo+hi)/2.0-res)/3.0 ELSE (a+ra+rp*(lo+hi)/2.0+pa+pp*(lo+hi)/2.0-res+s)/4.0 END))+MIN(pa+pp*(lo+hi)/2.0,(a+ra+rp*(lo+hi)/2.0+s-res)/3.0))-e+1e-12 THEN hi ELSE (lo+hi)/2.0 END,n+1 FROM bs WHERE n<80) SELECT scenario,period,lo AS maximum_purchase_usd_million,a+ra+rp*lo-res+MIN(s,MIN(shared_dollar_cap,CASE WHEN (a+ra+rp*lo+pa+pp*lo-res)<3.0*s THEN (a+ra+rp*lo+pa+pp*lo-res)/3.0 ELSE (a+ra+rp*lo+pa+pp*lo-res+s)/4.0 END))+MIN(pa+pp*lo,(a+ra+rp*lo+s-res)/3.0) AS borrowing_base_usd_million,MIN(commitment,a+ra+rp*lo-res+MIN(s,MIN(shared_dollar_cap,CASE WHEN (a+ra+rp*lo+pa+pp*lo-res)<3.0*s THEN (a+ra+rp*lo+pa+pp*lo-res)/3.0 ELSE (a+ra+rp*lo+pa+pp*lo-res+s)/4.0 END))+MIN(pa+pp*lo,(a+ra+rp*lo+s-res)/3.0))-(e+lo) AS funding_surplus_usd_million FROM bs WHERE n=80;